  AND `animation`.`facing` = `expected`.`facing`
WHERE (
  (BINARY REPLACE(REPLACE(`ai`.`avatar`, 'https://utfs.io/f/', 'https://ui0arpl8sm.ufs.sh/f/'), 'https://uploadthing.b-cdn.net/f/', 'https://ui0arpl8sm.ufs.sh/f/') <=> BINARY `expected`.`previousAvatar`
    AND `ai`.`avatarFacing` = `expected`.`previousFacing`)
  OR
  (BINARY REPLACE(REPLACE(`ai`.`avatar`, 'https://utfs.io/f/', 'https://ui0arpl8sm.ufs.sh/f/'), 'https://uploadthing.b-cdn.net/f/', 'https://ui0arpl8sm.ufs.sh/f/') <=> BINARY `expected`.`sourceAvatar`
    AND `ai`.`avatarFacing` = `expected`.`sourceFacing`)
)
ON DUPLICATE KEY UPDATE `animationId` = `AiSpriteAnimation`.`animationId`;
